// Normalizar y limitar a 15 noticias más recientes entre todas las fuentes
const allItems = $input.all();
const uniqueMap = new Map();

for (const item of allItems) {
  const json = item.json;
  const link = json.link || json.guid || json.url;
  if (link && !uniqueMap.has(link)) {
    uniqueMap.set(link, {
      titulo: json.title,
      resumen: json.contentSnippet || json.summary || json.title,
      enlace: link,
      fuente: json.creator || 'Google News',
      fecha_publicacion: json.isoDate ? json.isoDate.substring(0, 10) : new Date().toISOString().substring(0, 10)
    });
  }
}

const limited = Array.from(uniqueMap.values()).slice(0, 15);
return limited.map(n => ({ json: n }));

// Procesar la respuesta del modelo, calcular puntaje y filtrar no relevantes
const item = $input.item.json;
let iaRes = {};

try {
  const rawText = item.text || item.response || item.output || '{}';
  iaRes = typeof rawText === 'string' ? JSON.parse(rawText.replace(/```json|```/g, '').trim()) : rawText;
} catch (e) {
  iaRes = { relevante: false };
}

if (!iaRes.relevante) {
  return []; // Descartar si no es relevante
}

const p = Math.max(1, Math.min(5, parseInt(iaRes.probabilidad, 10) || 1));
const i = Math.max(1, Math.min(5, parseInt(iaRes.impacto, 10) || 1));
const puntaje = p * i;

let nivel = 'Bajo';
if (puntaje >= 15) nivel = 'Alto';
else if (puntaje >= 8) nivel = 'Medio';

const prioritaria = puntaje >= 15;

return [{
  json: {
    titulo: $('Unificar y Filtrar Duplicados (Máx 15)').item.json.titulo,
    resumen: $('Unificar y Filtrar Duplicados (Máx 15)').item.json.resumen,
    enlace: $('Unificar y Filtrar Duplicados (Máx 15)').item.json.enlace,
    fuente: $('Unificar y Filtrar Duplicados (Máx 15)').item.json.fuente,
    fecha_publicacion: $('Unificar y Filtrar Duplicados (Máx 15)').item.json.fecha_publicacion,
    factor: iaRes.factor || 'Económico',
    area: iaRes.area || 'Operaciones y logística',
    tipo_evento: iaRes.tipo_evento || 'otro',
    probabilidad: p,
    impacto: i,
    puntaje: puntaje,
    nivel: nivel,
    prioritaria: prioritaria,
    estado: 'pendiente',
    decision: 'pendiente',
    origen: 'n8n',
    explicacion: iaRes.explicacion || ''
  }
}];
